messages.body_plain:
Hi Henrik

Thanks for the reply.  Script I am following is as follows:
=================================================
library(aroma.affymetrix);
log <- Arguments$getVerbose(-4, timestamp=TRUE);
dataSetName <- "adeno_carcinoma";
chipTypes <- c("Mapping250K_Sty");
#-------------------------------------------------------------
#pairs file
#-------------------------------------------------------------
pairs <- matrix(c("88224","88240",
"68038","68054",
"68040","68056",
"67950","67966"), ncol=2, byrow=TRUE);
colnames(pairs) <- c("normal", "tumor");

# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
# Tests for setting up CEL sets and locating the CDF file
# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
csRList <- list();
system.time(for (chipType in chipTypes) {
  cs <- AffymetrixCelSet$byName(dataSetName, chipType=chipType,
verbose=log);
  print(cs);
  stopifnot(all(getNames(cs) %in% pairs));
  csRList[[chipType]] <- cs;
})
# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
# Allelic cross-talk calibration
# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
csList <- csRList;
csCList <- list();
system.time(for (chipType in names(csList)) {
  cs <- csList[[chipType]];
  acc <- AllelicCrosstalkCalibration(cs);
  print(acc);
  csC <- process(acc, verbose=log);
  print(csC);
  stopifnot(identical(getNames(csC), getNames(cs)));
  csCList[[chipType]] <- csC;
})

# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
# Probe-level modelling test (for CN analysis)
# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
csList <- csCList;
cesCnList <- list();
system.time(for (chipType in names(csList)) {
  cs <- csList[[chipType]];
  plm <- RmaCnPlm(cs, mergeStrands=TRUE, combineAlleles=TRUE,
shift=300);
  print(plm);
  fit(plm, verbose=log);
  ces <- getChipEffectSet(plm);
  print(ces);
  stopifnot(identical(getNames(ces), getNames(cs)));
  cesCnList[[chipType]] <- ces;
})

# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
# Fragment-length normalization test
# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
cesCnList <- cesCnList;
cesNList <- list();
system.time(for (chipType in names(csList)) {
  ces <- cesCnList[[chipType]];
  fln <- FragmentLengthNormalization(ces);
  print(fln);
  cesN <- process(fln, verbose=log);
  print(cesN);
  stopifnot(identical(getNames(cesN), getNames(ces)));
  cesNList[[chipType]] <- cesN;
})

# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
# Setup a paired CBS model
# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
-
# Split data set in (tumor, normal) pairs
sets <- list(tumor=list(), normal=list());
system.time(for (chipType in names(cesNList)) {
  ces <- cesNList[[chipType]];
  for (type in colnames(pairs)) {
    idxs <- match(pairs[,type], getNames(ces));
    sets[[type]][[chipType]] <- extract(ces, idxs);
  }
})
system.time(cns <- CbsModel(sets$tumor, sets$normal));
print(cns);

# Link the ChromosomeExplorer to the segmentation model
system.time(ce <- ChromosomeExplorer(cns));
print(ce);

# Fit the model for a few chromosomes
system.time(process(ce, arrays=1:2, chromosomes=c(2, 19),
verbose=log));
============================================================

Once you pointed out that CNSing is necessary before model setup, I
realized that step was not included in my script. From DNAcopy manual,
I understand that the object needs to be a CNA  object and it should
be smoothed before segmentation.

So here is my question: Does the object created after fragment length
normalization need to be an CNA object, followed by smoothing before
proceeding to segmentation ?

regards

suresh

